import { INTERNAL_applyBufferUsages, } from "../core/buffer/buffer.js";
import { TgpuBufferBindingImpl } from "../core/buffer/bufferBinding.js";
import { constant } from "../core/constant/tgpuConstant.js";
import { INTERNAL_restoreComputePipeline, } from "../core/pipeline/computePipeline.js";
import { INTERNAL_restoreRenderPipeline, } from "../core/pipeline/renderPipeline.js";
import { INTERNAL_restoreGuardedComputePipeline, INTERNAL_restoreRoot } from "../core/root/init.js";
import { accessor, mutableAccessor } from "../core/slot/accessor.js";
import { slot } from "../core/slot/slot.js";
